class Solution:
    def KDistanceNodes(self, root, target, K):
        def add_parent_pointers(node, parent=None):
            if node is None:
                return
            node.parent = parent
            add_parent_pointers(node.left, node)
            add_parent_pointers(node.right, node)

        def find_target(node, target):
            if node is None:
                return None
            if node.val == target:
                return node
            left = find_target(node.left, target)
            if left is not None:
                return left
            return find_target(node.right, target)

        def collect_k_distance_nodes(node, k, visited):
            if node is None or node in visited or k < 0:
                return []
            if k == 0:
                return [node.val]
            visited.add(node)
            result = []
            result.extend(collect_k_distance_nodes(node.left, k - 1, visited))
            result.extend(collect_k_distance_nodes(node.right, k - 1, visited))
            result.extend(collect_k_distance_nodes(node.parent, k - 1, visited))
            return result

        add_parent_pointers(root)
        target_node = find_target(root, target)
        result = collect_k_distance_nodes(target_node, K, set())
        result.sort()
        return result
